import{_ as a,o as t,c as i,a6 as e}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"SSR 是什么 · 一次请求的服务端旅程","description":"SSR 让服务器在收到请求时，就地把组件渲染成完整 HTML 再发给浏览器——首屏立刻可见、爬虫能读到内容。这一章走一遍这段服务端旅程，并点破它的代价：每次请求都要现算，很贵。","frontmatter":{"title":"SSR 是什么 · 一次请求的服务端旅程","description":"SSR 让服务器在收到请求时，就地把组件渲染成完整 HTML 再发给浏览器——首屏立刻可见、爬虫能读到内容。这一章走一遍这段服务端旅程，并点破它的代价：每次请求都要现算，很贵。","source":"https://daiw.org/manual/ssr/what-is-ssr"},"headers":[],"relativePath":"manual/computer-programming/ssr/what-is-ssr.md","filePath":"manual/computer-programming/ssr/what-is-ssr.md"}'),n={name:"manual/computer-programming/ssr/what-is-ssr.md"};function r(l,s,p,o,h,d){return t(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="ssr-是什么-·-一次请求的服务端旅程" tabindex="-1">SSR 是什么 · 一次请求的服务端旅程 <a class="header-anchor" href="#ssr-是什么-·-一次请求的服务端旅程" aria-label="Permalink to &quot;SSR 是什么 · 一次请求的服务端旅程&quot;">​</a></h1><p>SSR 让服务器在收到请求时，就地把组件渲染成完整 HTML 再发给浏览器——首屏立刻可见、爬虫能读到内容。这一章走一遍这段服务端旅程，并点破它的代价：每次请求都要现算，很贵。</p><p>SSR（Server-Side Rendering，服务端渲染）的定义，一句话就够：<strong>在服务器上把页面渲染成完整的 HTML 字符串，再连同数据一起发给浏览器。</strong> 浏览器一拿到就能显示内容——不必再等一大包 JS 跑完。</p><p>关键在于<strong>同一套组件代码，既在服务端跑、也在客户端跑</strong>（这叫「同构 / isomorphic」）。服务端跑一遍产出首屏 HTML，客户端再跑一遍把它「接管」过来（下一章的<a href="/Front2Full/manual/computer-programming/ssr/hydration">水合</a>）。</p><h2 id="一次-ssr-请求走了哪些路" tabindex="-1">一次 SSR 请求走了哪些路 <a class="header-anchor" href="#一次-ssr-请求走了哪些路" aria-label="Permalink to &quot;一次 SSR 请求走了哪些路&quot;">​</a></h2><p>用户点开一个 SSR 页面，服务器这一侧发生了这些事：</p><div class="language-mermaid vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TB</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[&quot;浏览器请求 /article/42&quot;] --&gt; B[&quot;服务器运行框架代码&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt; C[&quot;在服务端拉数据(查库 / 调 API)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt; D[&quot;把组件渲染成 HTML 字符串&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  D --&gt; E[&quot;把数据序列化,嵌进 HTML&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  E --&gt; F[&quot;把完整 HTML 发回浏览器&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  F --&gt; G[&quot;浏览器立刻显示内容(首屏出来了)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  G --&gt; H[&quot;后台下载 JS,水合成可交互应用&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>对比上一章 CSR 那条「拿到空壳才开始干活」的瀑布，差别一目了然：<strong>SSR 在服务端就把数据拉好、把内容画好了</strong>，浏览器拿到的第一份 HTML 里就有真东西。</p><h2 id="服务端这一步到底在干嘛" tabindex="-1">服务端这一步到底在干嘛 <a class="header-anchor" href="#服务端这一步到底在干嘛" aria-label="Permalink to &quot;服务端这一步到底在干嘛&quot;">​</a></h2><p>核心是把组件树<strong>渲染成 HTML 字符串</strong>。React 里是 <code>renderToString</code>（或更现代的 <code>renderToPipeableStream</code>，见<a href="/Front2Full/manual/computer-programming/ssr/streaming">流式渲染</a>），Vue 里是 <code>renderToString</code>，原理都一样：<strong>在没有浏览器、没有 DOM 的 Node 环境里，把组件「跑」成一段 HTML 文本。</strong></p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 服务端(示意):把 React 组件渲染成 HTML 字符串</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { renderToString } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;react-dom/server&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> html</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> renderToString</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">App</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> data</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{data} /&gt;);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">res.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`&lt;!DOCTYPE html&gt;&lt;div id=&quot;root&quot;&gt;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">html</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&lt;/div&gt;...\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>各框架把这套包了不同的「壳」，但底下是同一件事：</p><table tabindex="0"><thead><tr><th>框架</th><th>在服务端取数 / 渲染的入口</th></tr></thead><tbody><tr><td>Next.js(Pages)</td><td><code>getServerSideProps</code></td></tr><tr><td>Next.js(App Router)</td><td>异步 Server Component（默认）</td></tr><tr><td>Nuxt</td><td><code>asyncData</code> / <code>useFetch</code></td></tr><tr><td>SvelteKit</td><td><code>load</code>(server)</td></tr><tr><td>Remix / React Router</td><td><code>loader</code></td></tr></tbody></table><p>API 名字不同，你在服务端「拉数据 + 渲染」的这段活是一样的。<strong>理解了这段旅程，换框架只是换语法。</strong></p><h2 id="藏在-html-里的数据" tabindex="-1">藏在 HTML 里的数据 <a class="header-anchor" href="#藏在-html-里的数据" aria-label="Permalink to &quot;藏在 HTML 里的数据&quot;">​</a></h2><p>有个容易忽略但很关键的细节：服务端渲染完 HTML，还会把<strong>这次渲染用到的数据序列化成 JSON，一起塞进 HTML</strong>。你在 SSR 页面右键「查看源代码」，常能看到一大坨这样的东西：</p><div class="language-html vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;__NEXT_DATA__&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;application/json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {&quot;props&quot;:{&quot;article&quot;:{&quot;id&quot;:42,&quot;title&quot;:&quot;...&quot;}}}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>为什么要带上？因为客户端<strong>水合</strong>时需要<strong>和服务端一模一样的数据</strong>，才能把 HTML 正确接管（否则会「水合失配」，见下一章）。带上这份数据，客户端就<strong>不用再请求一次</strong>——直接复用，省一趟往返。</p><h2 id="ssr-顺手解决的两件事" tabindex="-1">SSR 顺手解决的两件事 <a class="header-anchor" href="#ssr-顺手解决的两件事" aria-label="Permalink to &quot;SSR 顺手解决的两件事&quot;">​</a></h2><p>回头看上一章 CSR 的痛点，SSR 一并解决了：</p><ul><li><strong>首屏快</strong>：HTML 里就有内容，浏览器立刻能画出来，FCP / LCP 大幅提前——不必等 JS。</li><li><strong>SEO 与分享卡片</strong>：内容、<code>&lt;title&gt;</code>、<code>og:</code> 元数据<strong>都在初始 HTML 里</strong>，爬虫直接读得到。搜索引擎能索引，微信 / Twitter 能形成分享卡片。</li></ul><h2 id="但-ssr-的代价-每次请求都要现算" tabindex="-1">但 SSR 的代价：每次请求都要现算 <a class="header-anchor" href="#但-ssr-的代价-每次请求都要现算" aria-label="Permalink to &quot;但 SSR 的代价：每次请求都要现算&quot;">​</a></h2><p>天下没有免费的午餐。SSR 把渲染搬回服务端，代价是——</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>每一个请求，服务器都要重新跑一遍「取数 + 渲染」。</strong> CSR 里服务器只发个静态壳（几乎零成本）；SSR 里服务器每次都要查库、调 API、把组件渲染成字符串——这是<strong>实打实的 CPU 和 I/O 开销</strong>。一个页面被访问一万次，服务器就渲染一万次。</p><p>这带来两个后果：① <strong>TTFB（首字节时间）变长</strong>——服务器得先渲染完才能发第一个字节；② <strong>扛不住流量</strong>——渲染很贵，并发一高，服务器就被自己的渲染开销压垮。</p><p><strong>这就是为什么本专栏要花一半篇幅讲缓存</strong>：让「渲染好的结果」被复用，而不是每次都现算。缓存，是 SSR 从「能用」到「能扛」的关键。这条线我们从<a href="/Front2Full/manual/computer-programming/ssr/why-cache">「为什么 SSR 必须缓存」</a> 开始展开。</p></div><h2 id="小结与下一章" tabindex="-1">小结与下一章 <a class="header-anchor" href="#小结与下一章" aria-label="Permalink to &quot;小结与下一章&quot;">​</a></h2><p>SSR 让服务器在请求到来时就地渲染出完整 HTML，换来了首屏快、SEO 好、分享成卡片；代价是每次请求都要现算，贵且慢（TTFB 长、难扛并发）。这个「代价」贯穿整个专栏，而缓存是它的解药。</p><p>但在讲缓存之前，还有个绕不开的概念：服务器发来的 HTML 是「死」的——它能显示，却还不能点击、不能交互。把它<strong>唤醒</strong>成一个活的应用，靠的是<strong>水合(hydration)</strong>。下一章讲透它。👉 <a href="/Front2Full/manual/computer-programming/ssr/hydration">水合：把死的 HTML 救活</a>。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li>[1] web.dev.「Rendering on the Web.」<a href="https://web.dev/articles/rendering-on-the-web" target="_blank" rel="noreferrer">https://web.dev/articles/rendering-on-the-web</a> —— SSR 定义与权衡。</li><li>[2] React 官方文档.「renderToPipeableStream / server APIs.」<a href="https://react.dev/reference/react-dom/server" target="_blank" rel="noreferrer">https://react.dev/reference/react-dom/server</a> —— 服务端渲染 API。</li><li>[3] Next.js 文档.「Rendering: Server Components / getServerSideProps.」<a href="https://nextjs.org/docs" target="_blank" rel="noreferrer">https://nextjs.org/docs</a> —— 框架层的 SSR 实现。</li></ul>`,29)])])}const c=a(n,[["render",r]]);export{g as __pageData,c as default};
